const COLORS={p1:'#2f7fd8',p2:'#ec6fa3',p3:'#f2c230',p4:'#b49be0',guest:'#3fae6a'},OP_LABELS={plus:['＋','たしざん'],minus:['−','ひきざん'],times:['×','かけざん'],divide:['÷','わりざん']};
