let profiles=C.freshProfiles(),profilesBroken=false,profilesRaw=null;
try{profilesRaw=localStorage.getItem(C.PROFILES_KEY);}catch(e){}
if(profilesRaw!==null){let parsed=null;try{parsed=JSON.parse(profilesRaw);}catch(e){}if(C.validProfiles(parsed))profiles=parsed;else profilesBroken=true;}else saveProfiles();
function saveProfiles(){if(profilesBroken)return false;try{localStorage.setItem(C.PROFILES_KEY,JSON.stringify(profiles));return true;}catch(e){return false;}}
// Save keeper: the chosen person's record, the copy kept before a reset and the backup file name go through here (the sound setting in drive.js is per device and stays out). The old v2 record is not read or changed.
const store={who:null,get key(){return C.recordKey(this.who);},get resetKey(){return C.resetKey(this.who);},get backupName(){return `keisan-tetsudo-${this.who}-backup.json`;},read(){return localStorage.getItem(this.key);},write(s){const encoded=JSON.stringify(s);localStorage.setItem(this.key,encoded);return encoded;},mine(e){return e.key===this.key;},keepBeforeReset(fallback){localStorage.setItem(this.resetKey,this.read()??fallback);},beforeReset(){const data=JSON.parse(localStorage.getItem(this.resetKey));return C.valid(data)&&data.version===3?data:null;},dropBeforeReset(){localStorage.removeItem(this.resetKey);}};
// Until someone is chosen, the screen shows an unsaved fresh record behind だれが あそぶ？.
let state=C.freshRecord('guest'),entry='',corrupt=false,storageOK=true,conflict=false,lastSaved=null;
function load(who){store.who=who;loadRest(who);streak={mode:null,n:0};usedAt={};sections=0;transferDue=false;state=C.freshRecord(who);entry='';corrupt=false;conflict=false;storageOK=true;lastSaved=null;try{const raw=store.read();lastSaved=raw;if(raw!==null){const parsed=JSON.parse(raw);if(C.valid(parsed)&&parsed.version===3)state=parsed;else corrupt=true;}}catch(e){storageOK=false;corrupt=true;}if(!corrupt){C.upgradeCards(state);if(state.target===null&&!state.pending)C.aim(state,null);}selected=state.current;}
function save(){if(store.who&&!corrupt&&!conflict){try{if(store.read()!==lastSaved){conflict=true;}else{if(JSON.stringify(state)!==lastSaved)state.at=Date.now();lastSaved=store.write(state);storageOK=true;}}catch(e){storageOK=false;}}
$('save-status').textContent=conflict?'別の画面で記録が更新されました。この画面を再読み込みしてください。':corrupt?'保存記録を読み込めません。元の記録を残して、今回は保存せず遊べます。':!storageOK?'保存できません。閉じる前にバックアップを保存してください。':profilesBroken?'なまえの記録を読み込めません。元の記録を残して、なまえは仮のまま遊べます。':'✓ つづきは このブラウザに ほぞんされるよ';
$('save-status').hidden=!(conflict||corrupt||!storageOK||profilesBroken);
$('keypad').querySelectorAll('button').forEach(b=>b.disabled=conflict);$('next').disabled=conflict;}
window.addEventListener('storage',e=>{if(store.who&&store.mine(e)&&e.newValue!==lastSaved){conflict=true;save();}if(e.key===C.PROFILES_KEY&&!profilesBroken){try{const p=JSON.parse(e.newValue);if(C.validProfiles(p)&&p.device===profiles.device){profiles=p;renderBadge();}}catch(err){}}});
let camera={x:0,y:0,width:1150,height:700},selected=state.current;
function mapAspect(){const w=$('map-wrap').clientWidth,h=$('map-wrap').clientHeight;return w>0&&h>0?w/h:camera.width/camera.height;}
function centerMap(id=state.current){const s=R.stations[id];const aspect=mapAspect();camera.width=1050;camera.height=camera.width/aspect;camera.x=s.x-camera.width/2;camera.y=s.y-camera.height/2;updateCamera();}
function updateCamera(){const b=R.bounds;camera.x=Math.max(b.x-camera.width/4,Math.min(camera.x,b.x+b.width-camera.width*.75));camera.y=Math.max(b.y-camera.height/4,Math.min(camera.y,b.y+b.height-camera.height*.75));$('map').setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.width} ${camera.height}`);$('map').querySelectorAll('.minor-label').forEach(t=>t.style.display=camera.width>2200?'none':'');$('map').querySelectorAll('.station-reading').forEach(t=>t.style.display=camera.width>1500?'none':'');
const scale=camera.width/Math.max(1,$('map').clientWidth),occupied=[];
const labels=[...$('map').querySelectorAll('.major-label')].sort((a,b)=>{const priority=t=>t.parentNode.dataset.station===state.current?0:cards.some(c=>!c.first&&c.station===t.parentNode.dataset.station)?1:2;return priority(a)-priority(b);});
for(const t of labels){const font=Math.max(27,12*scale);t.setAttribute('font-size',font);t.style.display='';if(camera.width>2200){const x=Number(t.getAttribute('x')),y=Number(t.getAttribute('y')),w=t.textContent.length*font,box={x:x-w/2,y:y-font,w,h:font*1.25};if(occupied.some(b=>box.x<b.x+b.w+8*scale&&box.x+box.w>b.x&&box.y<b.y+b.h+3*scale&&box.y+box.h>b.y)){t.style.display='none';}else occupied.push(box);}}
}

function zoom(f){const w=Math.max(650,Math.min(6500,camera.width*f)),ratio=w/camera.width;camera.x+=camera.width*(1-ratio)/2;camera.y+=camera.height*(1-ratio)/2;camera.height*=ratio;camera.width=w;updateCamera();}
function mapAll(){const pad=110,b={x:R.bounds.x-pad,y:R.bounds.y-pad,width:R.bounds.width+pad*2,height:R.bounds.height+pad*2},aspect=mapAspect();camera.width=Math.max(b.width,b.height*aspect);camera.height=camera.width/aspect;camera.x=b.x+(b.width-camera.width)/2;camera.y=b.y+(b.height-camera.height)/2;updateCamera();}
