function stampSVG(id){const s=R.stations[id],lines=R.lines.filter(l=>l.stations.includes(id)),ink=lines[0].color,scene=STAMP_LANDMARK[id]||(window.RailDrive?RailDrive.stationScene(id,lines.map(l=>l.id)):'sea'),key=`stamp-${++stampSeq}`,ring=2*Math.PI*90,fs=Math.min(44,132/s.name.length),rs=Math.min(18,84/s.reading.length);
return `<svg class="stamp-art" viewBox="0 0 200 200" aria-hidden="true"><defs><clipPath id="${key}"><circle cx="100" cy="100" r="76"/></clipPath></defs><g transform="rotate(${s.name.charCodeAt(0)%7-3} 100 100)">${lines.map((l,i)=>`<circle cx="100" cy="100" r="90" fill="none" stroke="${l.color}" stroke-width="12" stroke-dasharray="${ring/lines.length} ${ring}" stroke-dashoffset="${-i*ring/lines.length}" transform="rotate(-90 100 100)"/>`).join('')}<circle cx="100" cy="100" r="78" fill="none" stroke="${ink}" stroke-width="3"/>
<text x="100" y="50" text-anchor="middle" font-size="${rs}" font-weight="800" fill="${ink}">${esc(s.reading)}</text><text x="100" y="${80+fs/2.8}" text-anchor="middle" font-size="${fs}" font-weight="900" fill="${ink}">${esc(s.name)}</text><g clip-path="url(#${key})"><g transform="translate(100 110) scale(.98) translate(-100 -35)">${STAMP_ART[scene](ink)}</g></g></g></svg>`;}
// The press (as in the mock-up): the stamp comes down from large to its place in 0.3s and lands at about 0.2s, the page gives, then sparks; drive.js pon() plays the stamp sound file on the landing and the キラーン with the sparks (loaded ahead while the pad waits).
function stampBurst(id){const colors=[...R.lines.filter(l=>l.stations.includes(id)).map(l=>l.color),'#f5a524'];return Array.from({length:12},(_,i)=>`<i class="stamp-spark${i%2?' star':''}" aria-hidden="true" style="--a:${i*30+8}deg;--d:${i%3?112:132}px;--c:${colors[i%colors.length]}"></i>`).join('');}
function stampDay(id){const d=state.stamps?.[id];if(d){const [,m,day]=d.split('-').map(Number);return `${m}がつ ${day}にち`;}return id===C.opened(state)[0]?'しゅっぱつの えき':'まえに きたよ';}
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function directionArrow(from,to){const dx=to.x-from.x,dy=to.y-from.y;if(Math.abs(dy)<Math.abs(dx)*.35)return dx>0?'→':'←';if(Math.abs(dx)<Math.abs(dy)*.35)return dy>0?'↓':'↑';return dy>0?(dx>0?'↘':'↙'):(dx>0?'↗':'↖');}
function renderTravel(){const s=R.stations[state.current],line=R.lines.find(l=>l.stations.includes(s.id));$('current-name').textContent=s.name;$('current-reading').textContent=s.reading;$('current-line').style.background=line.color;$('current-line').textContent=line.name;
const options=C.adjacent(s.id);$('directions').innerHTML=options.map(e=>{const open=state.edges.includes(e.id),to=R.stations[e.to],route=R.lines.find(l=>l.id===e.line),active=state.target===e.to,remaining=C.credits(state)>0?'ためた回数で しゅっぱつ':`あと ${5-C.paid(state)%5}もん`;return `<button ${state.pending||conflict?'disabled':''} class="direction-choice forward ${open?'opened':''} ${active?'active':''}" style="--route-color:${route.color}" data-target="${e.to}" aria-pressed="${active}"><span class="direction-arrow" aria-hidden="true">${directionArrow(s,to)}</span><span class="direction-name">${esc(to.name)} <span class="direction-action">へ すすむ</span><small>${esc(to.reading)}</small></span><span class="direction-detail">${open?'かいつうずみ':remaining}</span></button>`;}).join('');
const n=C.credits(state);$('build-label').textContent=state.target?(n>0?`${n}えきぶん ためているよ`:`あと ${5-C.paid(state)%5}もんで ${state.target}！`):'ろせんずで 開通した駅をえらぼう';$('dots').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i<C.paid(state)%5?'on':''}"></i>`).join('')+`<b class="dots-train" style="--step:${C.paid(state)%5}" aria-hidden="true"><svg viewBox="0 0 34 20"><path d="M3 4h22a8 8 0 0 1 8 8v4H3z" fill="#fff" stroke="#16323c" stroke-width="2" stroke-linejoin="round"/><path d="M3 13h30" stroke="${line.color}" stroke-width="3"/><rect x="7" y="7" width="5" height="4" rx="1" fill="#16323c"/><rect x="15" y="7" width="5" height="4" rx="1" fill="#16323c"/><path d="M24 7h3l3 4h-6z" fill="#16323c"/><circle cx="9" cy="18" r="2" fill="#16323c"/><circle cx="26" cy="18" r="2" fill="#16323c"/></svg></b>`;$('use-credit').hidden=!(n>0&&state.target&&!state.pending);$('use-credit').textContent=`ためた回数で ${state.target}へ しゅっぱつ`;$('use-credit').disabled=conflict;$('quiz-goal').textContent=$('build-label').textContent;$('quiz-dots').innerHTML=Array.from({length:5},(_,i)=>`<i class="${i<C.paid(state)%5?'on':''}"></i>`).join('');$('quiz-start').disabled=!!state.pending||conflict;
const c=C.nearestReward(state,cards,true);$('next-card').innerHTML=c?`<img src="${c.image}" alt="${esc(c.name)}"><div><b>${esc(c.name)}</b><p>${esc(c.station)}駅でゲット<br>あと ${c.remaining}くかん${state.target?'（えらんだ方向）':''}</p></div>`:(C.earned(state).length===cards.length?'<div><b>すべての 車両に あえたね！</b><p>まだ白い駅にも、あいにいこう。</p></div>':'<div><b>この先の駅を つなげよう</b><p>別の方向には、まだ車両カードがあるよ。</p></div>');}
// The buttons are the operations this person has kinds for (set in おうちの方へ).
function render(){$('mode-tabs').innerHTML=C.modes(state).map(m=>`<button data-mode="${m}" class="${m===state.mode?'active':''}" aria-pressed="${m===state.mode}"${state.pending||conflict?' disabled':''}>${OP_LABELS[m].join(' ')}</button>`).join('');$('mode-tabs').classList.toggle('many',C.modes(state).length>2);$('question').textContent=`${state.problem.a} ${OP_LABELS[state.mode][0]} ${state.problem.b} =`;$('answer').textContent=state.solved?state.problem.result:(entry||'?');$('keypad').style.visibility=state.solved?'hidden':'visible';$('next').hidden=!state.solved;$('feedback').textContent=state.solved?'せいかい！':'こたえを いれてね';document.querySelector('.exercise').classList.toggle('solved',state.solved);renderTravel();renderMap();save();}
// After a section opens, drive it first (once per opening; `pending.drove` survives a reload), then show the usual reward. A trip on an opened section (`pending.ride`) is the drive alone: no stamp, card or reward screen. The train list is the one from before this opening, so a new card stays a surprise until the reward.
function openDrive(){const p=state.pending,e=C.edgeById[p.edge],from=e.a===p.station?e.b:e.a,next=C.adjacent(p.station).map(x=>x.to).find(id=>id!==from);RailDrive.open({from:R.stations[from],to:R.stations[p.station],next:next?R.stations[next]:null,line:R.lines.find(l=>l.id===e.line),train:C.train(state),ride:!!p.ride,owned:C.rideable(p.ride?state:{...state,edges:state.edges.filter(id=>id!==p.edge)}),cards,onTrain:id=>{state.train=id;save();},onDone:()=>{if(!state.pending)return;state.pending.drove=true;save();showReward();}});}
// The first opening gives the first card (Red Wing) before the drive, so the child sets off in the train they just got.
// A new station's stamp waits for the child to tap it ("ポン！"); the card and つぎへ come after.
