$('app-version').textContent=document.querySelector('meta[name="app-version"]')?.content||'不明';
$('update-app').onclick=async()=>{
const button=$('update-app');button.disabled=true;$('update-status').textContent='最新版を確認しています…';
try{
const url=new URL('index.html',document.baseURI);url.searchParams.set('update',Date.now().toString());
const response=await fetch(url.href,{cache:'no-store'});
if(!response.ok)throw Error('通信エラー '+response.status);
const html=await response.text();
const version=new DOMParser().parseFromString(html,'text/html').querySelector('meta[name="app-version"]')?.content;
if(!version)throw Error('更新データを確認できませんでした');
$('update-status').textContent='最新版を開きます。記録はそのまま残ります。';
location.replace(url.href);
}catch(error){button.disabled=false;$('update-status').textContent='更新できませんでした：'+error.message+'。通信を確認して、もう一度お試しください。';}
};
