$('map-full').onclick=()=>{const world=document.querySelector('.world'),on=!world.classList.contains('map-expanded');if(on)normalCamera={...camera};world.classList.toggle('map-expanded',on);$('map-full').textContent=on?'もどす':'大きく見る';if(on)mapAll();else{camera={...normalCamera};normalCamera=null;camera.height=camera.width/mapAspect();updateCamera();}};
const pointers=new Map();let gesture=null,moved=false;
$('map').addEventListener('pointerdown',e=>{pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});$('map').setPointerCapture(e.pointerId);moved=false;gesture={x:e.clientX,y:e.clientY,camera:{...camera},distance:pointers.size===2?Math.hypot(...(()=>{const p=[...pointers.values()];return[p[0].x-p[1].x,p[0].y-p[1].y];})()):null};});
$('map').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);if(gesture.distance){zoom(gesture.distance/d);gesture.distance=d;moved=true;}return;}const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;camera.x=gesture.camera.x-dx*camera.width/$('map').clientWidth;camera.y=gesture.camera.y-dy*camera.height/$('map').clientHeight;updateCamera();});
$('map').addEventListener('pointerup',e=>{if(!moved){const node=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-station]');if(node)showSelection(node.dataset.station);}pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('pointercancel',e=>{pointers.delete(e.pointerId);gesture=null;});$('map').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.station){e.preventDefault();showSelection(e.target.dataset.station);}});
$('map').addEventListener('wheel',e=>{if(e.ctrlKey){e.preventDefault();zoom(e.deltaY>0?1.08:.92);}},{passive:false});
function resizeMap(){if(document.querySelector('.world').classList.contains('map-expanded'))mapAll();else{const cy=camera.y+camera.height/2;camera.height=camera.width/mapAspect();camera.y=cy-camera.height/2;updateCamera();}}
window.addEventListener('resize',resizeMap);
if(window.visualViewport)window.visualViewport.addEventListener('resize',resizeMap);
new ResizeObserver(resizeMap).observe($('map-wrap'));
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||e.target.closest('#map,button,input,a'))return;if(e.key==='Enter'&&state.solved){e.preventDefault();$('next').click();}else if(/^\d$/.test(e.key)){e.preventDefault();key(e.key);}else if(e.key==='Backspace'){e.preventDefault();key('clear');}else if(e.key==='Enter'){e.preventDefault();key('submit');}});
$('legend').innerHTML=R.lines.map(l=>`<span><i style="--line:${l.color}"></i>${l.name}</span>`).join('');centerMap();render();openWho();
